//----------------------------------------------------------------------------------------------------------------------------------
// fx_fft.h - fixed-point real-input FFT for the on-scope spectrum analyser (fw 0.2.27, docs/plans/dpos350p-features.md 1.2)
//
// No libc, no float: int32 data, Q30 twiddles from a build-time quarter-wave cosine table (fx_fft_tables.c, generated by
// tools/gen_fft_tables.py), int64 products (SMULL on the ARM926). N real samples, N = 2^log2n, log2n 8..14 (256..16384).
// Method: N/2-point complex radix-2 DIT FFT of z[n] = x[2n] + i x[2n+1] (bit reversal fused into the windowed load), then the
// real split step. Overflow-free by construction: the input is scaled so that N * max|x| <= 2^29 (no partial DFT
// component exceeds 2^29, bounds in fx_fft.c), no per-stage scaling; 16-bit input keeps every bit up to N = 16384. Host-built and checked against numpy: host_tests/test_fft.py.
//
// Output levels are in centi-dB (0.01 dB) relative to 1 input unit RMS for a sine centred on a bin, i.e. a full-scale
// 8-bit sine of amplitude 127 codes reads 20*log10(127/sqrt(2)) = 39.07 dB on every window. The caller adds
// 20*log10(volts per unit) to get dBV.
//----------------------------------------------------------------------------------------------------------------------------------

#ifndef FX_FFT_H
#define FX_FFT_H

#include "types.h"

#define FX_FFT_LOG2_MIN     8
#define FX_FFT_LOG2_MAX     14
#define FX_FFT_N_MAX        (1 << FX_FFT_LOG2_MAX)

#define FX_WIN_RECT         0
#define FX_WIN_HANN         1
#define FX_WIN_FLATTOP      2       //Matlab flattopwin coefficients (5 terms), periodic
#define FX_WIN_COUNT        3

#define FX_CDB_FLOOR        (-32000)  //centi-dB value for a zero bin

//Memory the caller provides, in int32 words, both 8-byte aligned: plan (window N + twiddles N), work buffer N + 2.
#define FX_FFT_WIN_WORDS(log2n)   (2 << (log2n))
#define FX_FFT_BUF_WORDS(log2n)   ((1 << (log2n)) + 2)

typedef struct
{
  int    log2n;
  int    window;
  int32 *win;           //Q30 window, all N points (pairs load as one LDRD), then N/2 twiddle pairs (c, s) of W_N^k
  int32 *buf;           //after a run: bins k = 0..N/2 as re, im pairs (2 * X_k scaled by 2^shift)
  int    shift;         //input scale of the last run: buf holds 2 * 2^shift * X_k (shift may be negative)
  int32  norm_q16;      //level term in log2 Q16 from the window sum (fx_fft_init)
} FX_FFT;

//Set up a plan: fills the window table. Returns 0, or -1 for a bad log2n or window or a buffer not 8-byte aligned.
int  fx_fft_init(FX_FFT *p, int log2n, int window, int32 *win, int32 *buf);

//Window, scale and transform N samples. u8: x[n] - offset (8-bit ADC codes, x 2-byte aligned, offset 0..255, clamped);
//i32: x[n] - offset,
//x 8-byte aligned, |x - offset| < 2^28
//(inputs wider than 29 - log2n bits are rounded to that width).
void fx_fft_run_u8(FX_FFT *p, const uint8 *x, int32 offset);
void fx_fft_run_i32(FX_FFT *p, const int32 *x, int32 offset);
//u16: 16-bit records of the FPGA 0x1534 filter (C only); every bit is kept up to N = 8192 (|x - offset| <= 32768)
void fx_fft_run_u16(FX_FFT *p, const uint16 *x, int32 offset);

//Bin power of the last run in centi-dB (see above) plus offset, bins k = first..first + count - 1 (<= N/2) into out;
//FX_CDB_FLOOR marks an empty bin, other values are clamped to FX_CDB_FLOOR + 1..32767.
void fx_fft_cdb(const FX_FFT *p, int first, int count, int32 offset, int16 *out);

//Helpers, exposed for the display code and the host tests.
int32  fx_log2_q16(uint64 v);            //log2(v) in Q16 (v > 0), error < 2^-16 after interpolation
int32  fx_cdb_from_q16(int32 log2q16);   //10 * log10(2^(x / 65536)) in centi-dB
uint32 fx_enbw_milli(int window);        //equivalent noise bandwidth in milli-bins (1000 rect, 1500 Hann, 3770 flat-top)
int32  fx_cos_q30(uint32 k, int log2n);  //cos(2 pi k / N) in Q30, any k

#endif
